247	 * Validates the plan folder basename matches `YYYY-MM-DD-{project-name}`.
248	 * Wraps planFolderBasename() so any thrown error becomes a failed check.
249	 */

101	  } catch {
102	    return { ...EMPTY_RESOLUTION, logFilename };
103	  }
104	
105	  const lines = raw.split('\n').filter((l) => l.trim().length > 0);
106	
107	  // Walk backwards to find the last summarisable event.
108	  for (let i = lines.length - 1; i >= 0; i--) {
109	    try {
110	      const parsed = JSON.parse(lines[i]!) as Record<string, unknown>;
111	      const summary = formatProgressEntry(parsed);
112	      if (summary !== null) {
113	        const lastAction = typeof parsed['action'] === 'string' ? parsed['action'] : null;
114	        return {
115	          summary,
116	          lastAction,
117	          logFilename,
118	          hasStageActivity: lastAction !== null && lastAction !== 'run_start',
119	        };
120	      }
121	    } catch {
122	      // Malformed JSON line — skip.
123	    }
124	  }
125	
126	  // File was readable but contained no summarisable events.
127	  return { ...EMPTY_RESOLUTION, logFilename };
128	}

