 76	// ---------------------------------------------------------------------------
 77	// AC-1: projectExists is true when the ledger file exists
 78	// ---------------------------------------------------------------------------
 79	
 80	describe('getQueue — AC-1: projectExists is true when ledger file exists', () => {
 81	  let env: TestEnv;
 82	
 83	  beforeEach(async () => {
 84	    env = await setup();
 85	  });
 86	
 87	  afterEach(async () => {
 88	    await teardown(env.tempDir);
 89	  });
 90	
 91	  it('returns projectExists: true for an entry whose project ledger exists', async () => {
 92	    const slug = '2026-05-20-my-feature';
 93	    await writeQueue(env.logsDir, slug);
 94	    await createProjectLedger(env.ledgerRoot, slug);
 95	
 96	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
 97	
 98	    expect(entries).toHaveLength(1);
 99	    expect(entries[0].projectExists).toBe(true);
100	    expect(entries[0].expectedSlug).toBe(slug);

101	  });
102	});
103	
104	// ---------------------------------------------------------------------------
105	// AC-2: projectExists is false when the ledger file does not exist
106	// ---------------------------------------------------------------------------
107	
108	describe('getQueue — AC-2: projectExists is false when ledger file is absent', () => {
109	  let env: TestEnv;
110	
111	  beforeEach(async () => {
112	    env = await setup();
113	  });
114	
115	  afterEach(async () => {
116	    await teardown(env.tempDir);
117	  });
118	
119	  it('returns projectExists: false for an entry with no project ledger on disk', async () => {
120	    const slug = '2026-05-20-no-ledger';
121	    await writeQueue(env.logsDir, slug);
122	    // Intentionally do NOT create a project ledger for this slug.
123	
124	    const entries = await getQueue({ logsDir: env.logsDir, ledgerRoot: env.ledgerRoot });
125	
126	    expect(entries).toHaveLength(1);
127	    expect(entries[0].projectExists).toBe(false);
128	    expect(entries[0].expectedSlug).toBe(slug);
129	  });
130	});
