136	describe('getQueue — validator: rejects entry with empty expectedSlug', () => {
137	  let env: TestEnv;
138	
139	  beforeEach(async () => {
140	    env = await setup();
141	  });
142	
143	  afterEach(async () => {
144	    await teardown(env.tempDir);
145	  });
146	
147	  it('filters out an entry whose expectedSlug is an empty string', async () => {
148	    // Write a queue with one entry that has an empty expectedSlug.
149	    const invalidEntry = {
150	      id:           'test-empty-slug',
